// ── Valida e normaliza o payload recebido do Cockpit ──────────────────────
const body = $input.first().json.body || $input.first().json;
const { nicho, cidades, meta_semanal = 140 } = body;

if (!nicho)    throw new Error('Payload inválido: campo "nicho" é obrigatório.');
if (!cidades)  throw new Error('Payload inválido: campo "cidades" é obrigatório (string ou array).');

const cidadesArr = Array.isArray(cidades) ? cidades : [cidades];

// REGRA GLOBAL: Máximo de 20 leads por rodada de execução
let lote_diario = Math.ceil(meta_semanal / 7);
if (lote_diario > 20) lote_diario = 20; 

// Buffer reduzido para não sobrecarregar Apify, mantendo o limite fixo em teto de segurança
const apify_limit = lote_diario + 5;

// Grava a missão no staticData para uso nos próximos nós
$workflow.staticData.missao = {
  nicho,
  cidades: cidadesArr,
  meta_semanal,
  lote_diario,
  inicio: new Date().toISOString()
};

// Gera um item por cidade (cada um dispara um run separado no Apify)
return cidadesArr.map(cidade => ({
  json: {
    nicho,
    cidade,
    lote_diario,
    apify_limit,
    search_query: `${nicho} ${cidade}`
  }
}));

// A resposta do Apify vem em data.defaultDatasetId
const runData = $input.item.json.data || $input.item.json;

if (!runData.defaultDatasetId) {
  throw new Error(`Apify run falhou ou não retornou dataset. Status: ${runData.status || 'desconhecido'}`);
}

if (runData.status !== 'SUCCEEDED') {
  throw new Error(`Apify run não concluiu com sucesso. Status: ${runData.status}`);
}

return {
  json: {
    datasetId: runData.defaultDatasetId,
    runId: runData.id,
    itemCount: runData.stats?.itemCount || 0,
    cidade: $workflow.staticData.missao?.cidades?.[0] || ''
  }
};

// ── Recupera resultados do Apify e blacklist do Redis ─────────────────────
const apifyItems = $('HTTP — Apify: Busca Dataset').all();
const redisItem  = $('Redis — GET Blacklist Cache').first();
const blacklist  = JSON.parse(redisItem.json.value || '[]').map(u => u.toLowerCase().trim());

const missao = $workflow.staticData.missao || {};

// ── Keywords que identificam concorrentes / serviços similares ─────────────
const CONCORRENTE_KW = [
  'design', 'designer', 'criativo', 'criativa', 'arte', 'artista',
  'portfolio', 'portfólio', 'branding', 'logo', 'logotipo',
  'agência', 'agencia', 'marketing', 'identidade visual', 'marca'
];

const qualificados = [];
const descartados  = { blacklist: 0, nao_b2b: 0, concorrente: 0, inativo: 0, score_baixo: 0 };

for (const item of apifyItems) {
  // O Apify pode retornar o array direto ou embrulhado
  const profiles = Array.isArray(item.json) ? item.json : [item.json];

  for (const p of profiles) {
    if (!p || !p.username) continue;

    const username = (p.username || '').toLowerCase().trim();

    // ── 0. Blacklist ───────────────────────────────────────────────────────
    if (blacklist.includes(username)) { descartados.blacklist++; continue; }

    // Normaliza campos (Apify usa camelCase)
    const is_business = p.isBusinessAccount === true;
    const bio         = (p.biography || '').toLowerCase();
    const ext_url     = (p.externalUrl || p.external_url || '').toLowerCase().trim();
    const followers   = p.followersCount || p.followersCount || 0;
    const pic_url     = p.profilePicUrlHD || p.profilePicUrl || '';

    // Pega data do post mais recente
    const latestPosts = p.latestPosts || [];
    const latestTimestamp = latestPosts.length > 0
      ? (latestPosts[0].timestamp || latestPosts[0].takenAtTimestamp || null)
      : null;

    // ── 1. Filtro B2B (conta comercial OU URL externa válida) ──────────────
    if (!is_business && !ext_url) { descartados.nao_b2b++; continue; }

    // ── 2. Filtro Anti-Concorrente ─────────────────────────────────────────
    if (CONCORRENTE_KW.some(kw => bio.includes(kw))) { descartados.concorrente++; continue; }

    // ── 3. Lead Score ──────────────────────────────────────────────────────
    let score = 0;

    // Tamanho do público: sweet spot para pequenos negócios
    if (followers >= 1000 && followers <= 15000) score += 20;

    // Atividade recente
    if (latestTimestamp) {
      const postDate = new Date(
        typeof latestTimestamp === 'number' ? latestTimestamp * 1000 : latestTimestamp
      );
      const daysSince = (Date.now() - postDate.getTime()) / 86400000;
      if (daysSince > 30) { descartados.inativo++; continue; } // perfil abandonado
      if (daysSince <= 7) score += 15;                         // postou essa semana
    }

    // Amadorismo digital = oportunidade de venda de identidade visual
    const isAmateur = !ext_url ||
      ext_url.includes('linktr.ee') ||
      ext_url.includes('beacons')   ||
      ext_url.includes('wa.me')     ||
      ext_url.includes('api.whatsapp');
    if (isAmateur) score += 15;

    // ── Aprovação mínima ───────────────────────────────────────────────────
    if (score < 40) { descartados.score_baixo++; continue; }

    qualificados.push({
      json: {
        Username:        p.username,
        Nome_Empresa:    p.fullName || p.username,
        Bio:             p.biography || '',
        Link_IG:         `https://www.instagram.com/${p.username}/`,
        External_URL:    p.externalUrl || '',
        Lead_Score:      score,
        Followers:       followers,
        Status:          'Curadoria',
        Foto_Perfil_URL: pic_url,
        Data_Entrada:    new Date().toISOString(),
        Nicho:           missao.nicho  || '',
        Cidade:          missao.cidades ? missao.cidades[0] : '',
        is_business:     is_business
      }
    });
  }
}

// Log de resultado (visível nas execuções do n8n)
console.log(`[SDR] Qualificados: ${qualificados.length} | Descartados:`, JSON.stringify(descartados));

// Marca resultado no staticData para o Respond final
$workflow.staticData.ultima_mineracao = {
  qualificados: qualificados.length,
  descartados,
  timestamp: new Date().toISOString()
};

if (qualificados.length === 0) {
  return [{ json: { _sem_leads: true, total: 0, descartados } }];
}

return qualificados;

// Agrega todos os leads do lote atual no formato de Bulk Create da API do Airtable
const records = items.map(item => ({
  fields: {
    Username:         item.json.Username        || '',
    Nome_Empresa:     item.json.Nome_Empresa     || '',
    Bio:              item.json.Bio              || '',
    Link_IG:          item.json.Link_IG          || '',
    External_URL:     item.json.External_URL     || '',
    Lead_Score:       item.json.Lead_Score       || 0,
    Followers:        item.json.Followers        || 0,
    Status:           'Curadoria',
    // Foto_Perfil: Airtable baixa a imagem pelo URL automaticamente
    Foto_Perfil: item.json.Foto_Perfil_URL
      ? [{ url: item.json.Foto_Perfil_URL }]
      : [],
    Data_Entrada: item.json.Data_Entrada || new Date().toISOString(),
    Nicho:        item.json.Nicho        || '',
    Cidade:       item.json.Cidade       || '',
    is_business:  item.json.is_business  === true
  }
}));

return [{ json: { records, count: records.length } }];

